const { parentPort, workerData } = require('node:worker_threads');
const vm = require('node:vm');
function serializeError(error) {
  let name = 'Error';
  let message = 'Experiment policy execution failed';
  let code;
  try {
    if (error && typeof error === 'object') {
      if (typeof error.name === 'string') name = error.name.slice(0, 128);
      if (typeof error.message === 'string') message = error.message.slice(0, 512);
      if (typeof error.code === 'string') code = error.code.slice(0, 128);
    }
  } catch {}
  return { name, message, code };
}
try {
  const sandboxGlobals = Object.create(null);
  sandboxGlobals.__inputJson = workerData.inputJson;
  const sandbox = vm.createContext(sandboxGlobals, {
    name: 'experiment-policy', codeGeneration: { strings: false, wasm: false },
  });
  const script = new vm.Script(workerData.program, { filename: 'experiment-policy.js' });
  const serialized = script.runInContext(sandbox, { timeout: workerData.executionTimeoutMs });
  if (typeof serialized !== 'string') throw new Error('Experiment policy returned a non-serializable result');
  if (Buffer.byteLength(serialized, 'utf8') > workerData.maxResultBytes) throw new Error('Experiment policy result exceeds the size limit');
  parentPort.postMessage({ type: 'success', serialized });
} catch (error) {
  parentPort.postMessage({ type: 'error', error: serializeError(error) });
}
